// Agent-02 (frozen strategy v1.0) + Agent-08 (risk caps). Mirror of engine/ahos_backtest.py
const P = {ema:20, atr:14, volSma:20, volMult:1.2, slAtr:1.5, tpAtr:2.0, lev:2.0, risk:0.02};
const killed = $('Kill Flag Check').first().json.killed === true;
const rows = $input.all().map(i => i.json);
const bySym = {};
for (const r of rows) { (bySym[r.symbol] = bySym[r.symbol] || []).push({ts:r.ts, o:+r.open, h:+r.high, l:+r.low, c:+r.close, v:+r.volume}); }
const out = [];
for (const sym of ['BTCUSDT','ETHUSDT','SOLUSDT']) {
  if (killed) { out.push({ json: { symbol: sym, decision: 'NO_TRADE', reason: 'kill_switch_active (Agent-04 halt flag set)' } }); continue; }
  const d = (bySym[sym] || []).sort((a,b) => a.ts < b.ts ? -1 : 1);
  if (d.length < P.volSma + 2) { out.push({ json: { symbol: sym, decision: 'NO_TRADE', reason: 'insufficient data' } }); continue; }
  const k = 2/(P.ema+1); let e = d[0].c; const ema = [];
  for (let i=0;i<d.length;i++){ e = i===0 ? d[0].c : d[i].c*k + e*(1-k); ema.push(e); }
  const a0 = Math.max(d[1].h-d[1].l, Math.abs(d[1].h-d[0].c), Math.abs(d[1].l-d[0].c)); let a = a0; const atr=[0,a];
  for (let i=2;i<d.length;i++){ const tr = Math.max(d[i].h-d[i].l, Math.abs(d[i].h-d[i-1].c), Math.abs(d[i].l-d[i-1].c)); a = (a*(P.atr-1)+tr)/P.atr; atr.push(a); }
  let vsum=0; const vsma = d.map((r,i)=>{ vsum+=r.v; if(i>=P.volSma) vsum-=d[i-P.volSma].v; return i>=P.volSma-1 ? vsum/P.volSma : NaN; });
  const i = d.length-1;
  const sigL = d[i].c > ema[i] && d[i].v > P.volMult*vsma[i] && atr[i]>0;
  const sigS = d[i].c < ema[i] && d[i].v > P.volMult*vsma[i] && atr[i]>0;
  if (!sigL && !sigS) { out.push({ json: { symbol: sym, decision: 'NO_TRADE', reason: 'no signal (trend/volume filter)' } }); continue; }
  const side = sigL ? 'LONG' : 'SHORT';
  const entry = d[i].c;
  const dist = P.slAtr*atr[i];
  const equity = 100; const notional = Math.min(P.risk*equity/(dist/entry), P.lev*equity);
  const sl = sigL ? entry-dist : entry+dist;
  const tp = sigL ? entry + (P.tpAtr/P.slAtr)*dist : entry - (P.tpAtr/P.slAtr)*dist;
  out.push({ json: { symbol: sym, decision: side, entry:+entry.toFixed(8), sl:+sl.toFixed(8), tp:+tp.toFixed(8), notional:+notional.toFixed(4), leverage:P.lev, risk_percent:P.risk*100, confidence:0.55, reason:'EMA20 trend + vol>1.2xSMA20, ATR14 bracket (frozen v1.0)' } });
}
return out;

// Agent-04 kill-switch also enforced upstream; here only mode resolution
const mode = $env.AHOS_MODE || 'PAPER';
return $input.all().map(i => ({ json: { ...i.json, mode } }));

